/**
 * Core ServiceList Components
 * Provides low-level access to ServiceListService via render props
 */
import React from 'react';
import { type ServiceListServiceConfig, type QueryOptions } from '../../../services/service-list/service-list.js';
import type { PagingMetadata, ServiceWithAvailabilityItem } from '../../../api/query-services/index.js';
/**
 * Props for ServiceList.Root component
 */
export interface RootProps {
    children: React.ReactNode;
    serviceListConfig: ServiceListServiceConfig;
}
/**
 * Root component that provides ServiceList service context.
 *
 * @component
 * @example
 * ```tsx
 * <ServiceList.Root serviceListConfig={{ services: myServices }}>
 *   {children}
 * </ServiceList.Root>
 * ```
 */
export declare function Root(props: RootProps): React.ReactNode;
/**
 * Props for Services render prop component
 */
